// Generated from the Maple2 server's trigger code (TriggerFunctionMapping, TriggerContext) and its packet writers. Each
// action names the writers its route ends in; each writer has one body the server wrote with sample values, or none
// where the writer needs live field objects (those get an empty-body dispatch probe).
namespace Ms2Godot.Tests;

public static class TriggerSweepRoutes
{
    /// <summary>Packet: the route ends in the writers. ServerOnly: no packet (server state, a log line or an empty
    /// method). LogOnly: the server only logs it, a server gap. Deep: the route was not traced to its end (STILL-OPEN).</summary>
    public enum Route { Packet, ServerOnly, LogOnly, Deep }

    /// <param name="Raw">The action name in the trigger XML.</param>
    /// <param name="Split">"attr=value" for an action the server splits by an attribute, else empty.</param>
    /// <param name="Name">The server's action.</param>
    /// <param name="Writers">The packet writers ("Class.Method" or "Class.Method[variant]"), comma separated.</param>
    /// <param name="Server">The server method and its file:line.</param>
    public readonly record struct Action(string Raw, string Split, string Name, Route Route, string Writers, string Note, string Server);

    /// <param name="Hex">The body after the opcode; null for a writer that needs live objects (a dispatch probe).</param>
    public readonly record struct Body(string Writer, ushort Opcode, string Hex, string Note);

